css:
.d-rd2{position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;width:100%;max-width:340px;height:190px;border:1px solid var(--line);border-radius:10px;background:var(--paper);touch-action:none;cursor:grab;overflow:hidden}
.d-rd2-knob{position:relative;width:110px;height:110px;border-radius:50%;border:1px solid var(--ink);background:radial-gradient(circle at 50% 38%,color-mix(in srgb,var(--ink) 14%,var(--paper)),var(--paper) 70%)}
.d-rd2-knob:after{content:"";position:absolute;inset:10px;border-radius:50%;border:1px dashed var(--line)}
.d-rd2-knob span{position:absolute;left:50%;top:6px;width:2px;height:22px;margin-left:-1px;background:var(--ink-vermilion);transform-origin:50% 49px;border-radius:999px}
.d-rd2 b{font-family:var(--font-mono);font-size:21px;letter-spacing:-.01em}
.d-rd2 em{font-style:normal;font-family:var(--font-mono);font-size:9px;letter-spacing:.06em;color:var(--faint)}

init:
root => {
  var box = root.querySelector('[data-dial]');
  var knob = root.querySelector('[data-knob]');
  var needle = root.querySelector('[data-needle]');
  var val = root.querySelector('[data-val]');
  if (!box || !knob || !needle) return;
  var steps = 12, step = 30, idx = 6, dragging = false, lastAngle = 0;
  var render = function () { needle.style.transform = 'rotate(' + (idx * step - 90) + 'deg)'; if (val) val.textContent = String(idx); };
  var angleOf = function (e) { var r = knob.getBoundingClientRect(); var cx = r.left + r.width / 2, cy = r.top + r.height / 2; return Math.atan2(e.clientY - cy, e.clientX - cx) * 180 / Math.PI; };
  box.addEventListener('pointerdown', function (e) { dragging = true; lastAngle = angleOf(e); box.setPointerCapture(e.pointerId); box.style.cursor = 'grabbing'; });
  box.addEventListener('pointermove', function (e) {
    if (!dragging) return;
    var a = angleOf(e), d = a - lastAngle;
    if (d > 180) d -= 360; if (d < -180) d += 360;
    lastAngle = a;
    idx = Math.max(0, Math.min(steps, idx + d / step));
    var snapped = Math.round(idx);
    needle.style.transform = 'rotate(' + (idx * step - 90).toFixed(1) + 'deg)';
    if (val) val.textContent = String(snapped);
  });
  var end = function () { if (!dragging) return; dragging = false; idx = Math.round(idx); box.style.cursor = 'grab'; render(); };
  box.addEventListener('pointerup', end);
  box.addEventListener('pointercancel', end);
  render();
}
